                  animation: "bounce 2s ease-in-out infinite",
                }}
              >
                🔍
              </span>
              <input
                type="text"
                placeholder="브랜드, 제품명, 키워드로 검색... (예: 롬앤, 비타민C, 쿠션)"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onFocus={() => setIsSearchFocused(true)}
                onBlur={() => setIsSearchFocused(false)}
                style={{
                  flex: 1,
                  border: "none",
                  outline: "none",
                  fontSize: 16,
                  background: "transparent",
                  color: "#333",
                  fontWeight: 500,
                }}
              />
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery("")}
                  style={{
                    background: "linear-gradient(135deg, #ff4d88, #ff6b9d)",
                    border: "none",
                    borderRadius: 25,
                    padding: "10px 20px",
                    color: "#fff",
                    fontSize: 13,
                    fontWeight: 700,
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                    boxShadow: "0 4px 15px rgba(255,77,136,0.3)",
                    transition: "all 0.2s ease",
                  }}
                  onMouseOver={(e) =>
                    (e.currentTarget.style.transform = "scale(1.05)")
                  }
                  onMouseOut={(e) =>
                    (e.currentTarget.style.transform = "scale(1)")
                  }
                >
                  ✕ 초기화
                </button>
              )}
            </div>

            {/* 인기 검색어 */}
            {!searchQuery && (
              <div
                style={{
                  marginTop: 16,
                  display: "flex",
                  alignItems: "center",
                  gap: 12,
                  flexWrap: "wrap",
                  animation: "slideUp 0.5s ease-out",
                }}
              >
                <span
                  style={{
                    background: "linear-gradient(135deg, #ff4d88, #ff6b9d)",
                    color: "#fff",
                    padding: "6px 14px",
                    borderRadius: 20,
                    fontSize: 12,
                    fontWeight: 700,
                    display: "flex",
                    alignItems: "center",
                    gap: 6,
                  }}
                >
                  🔥 인기 검색
                </span>
                {[
                  "롬앤",
                  "클리오",
                  "이니스프리",
                  "에스쁘아",
                  "비타민C",
                  "수분크림",
                  "틴트",
                ].map((keyword, idx) => (
                  <button
                    key={keyword}
                    onClick={() => setSearchQuery(keyword)}
                    style={{
                      background: "rgba(255,255,255,0.9)",
                      backdropFilter: "blur(10px)",
                      border: "1px solid rgba(255,77,136,0.2)",
                      borderRadius: 20,
                      padding: "8px 16px",
                      color: "#ff4d88",
                      fontSize: 13,
                      fontWeight: 600,
                      cursor: "pointer",
                      transition: "all 0.3s ease",
                      animation: `slideUp 0.4s ease-out ${idx * 0.05}s both`,
                    }}
                    onMouseOver={(e) => {
                      e.currentTarget.style.background =
                        "linear-gradient(135deg, #ff4d88, #ff6b9d)";
                      e.currentTarget.style.color = "#fff";
                      e.currentTarget.style.transform = "translateY(-3px)";
                      e.currentTarget.style.boxShadow =
                        "0 8px 20px rgba(255,77,136,0.3)";
                    }}
                    onMouseOut={(e) => {
                      e.currentTarget.style.background =
                        "rgba(255,255,255,0.9)";
                      e.currentTarget.style.color = "#ff4d88";
                      e.currentTarget.style.transform = "translateY(0)";
                      e.currentTarget.style.boxShadow = "none";
                    }}
                  >
                    {keyword}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* 카테고리 버튼들 */}
          <div
            style={{
              display: "flex",
              gap: 12,
              overflowX: "auto",
              paddingBottom: 12,
              background: "rgba(255,255,255,0.6)",
              backdropFilter: "blur(10px)",
              borderRadius: 20,
              padding: "16px 20px",
            }}
          >
            {[
              { id: "all", name: "전체", icon: "✨" },
              { id: "skincare", name: "스킨케어", icon: "💧" },
              { id: "makeup", name: "메이크업", icon: "💄" },
              { id: "bodycare", name: "바디케어", icon: "🧴" },
              { id: "fashion", name: "패션", icon: "👗" },
              { id: "lifestyle", name: "라이프스타일", icon: "🏠" },
            ].map((cat) => (
              <button
                key={cat.id}
                onClick={() => setActiveCategory(cat.id)}
                style={{
                  padding: "10px 18px",
                  borderRadius: 20,
                  border:
                    activeCategory === cat.id
                      ? "2px solid #ff4d88"
                      : "1px solid #e6eefb",
                  background:
                    activeCategory === cat.id
                      ? "linear-gradient(135deg, #fff0f5, #fff)"
                      : "#fff",
                  color: activeCategory === cat.id ? "#ff4d88" : "#666",
                  fontWeight: activeCategory === cat.id ? 600 : 400,
                  fontSize: 13,
                  whiteSpace: "nowrap",
                  cursor: "pointer",
                  display: "flex",
                  alignItems: "center",
                  gap: 6,
                  transition: "all 0.2s ease",
                }}
              >
                <span>{cat.icon}</span> {cat.name}
              </button>
            ))}
          </div>
        </div>

        {/* 리뷰 리스트 */}
        <div ref={reviewSectionRef}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: 16,
            }}
          >
            <h3 style={{ margin: 0, fontSize: 18 }}>🔥 최신 리뷰</h3>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              {[
                { id: "all", name: "전체", icon: "📋" },
                { id: "photo", name: "사진리뷰", icon: "📷" },
                { id: "text", name: "글리뷰", icon: "✏️" },
              ].map((type) => (
                <button
                  key={type.id}
                  onClick={() => setReviewType(type.id)}
                  style={{
                    padding: "6px 12px",
                    borderRadius: 20,
                    border:
                      reviewType === type.id
                        ? "2px solid #ff4d88"
                        : "1px solid #e0e0e0",
                    background:
                      reviewType === type.id ? "rgba(255,77,136,0.1)" : "#fff",
                    color: reviewType === type.id ? "#ff4d88" : "#666",
                    fontSize: 12,
                    fontWeight: reviewType === type.id ? 700 : 500,
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    gap: 4,
                    transition: "all 0.2s ease",
                  }}
                >
                  <span>{type.icon}</span>
                  <span>{type.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div style={{ color: "#888", fontSize: 13, marginBottom: 12 }}>
            {filteredReviews.length}개의 리뷰
            {searchQuery && (
              <span
                style={{ marginLeft: 8, color: "#ff4d88", fontWeight: 600 }}
              >
                "{searchQuery}" 검색 결과
              </span>
            )}
          </div>

          <div className="reviews-grid">
            {filteredReviews.length > 0 ? (
              filteredReviews.map((r) => (
                <div key={r._id} className="feed-card">
                  <ReviewCard
                    id={r._id}
                    username={getUsernameFromAuthor(r.author)}
                    brand={r.brand}
                    product={r.product}
                    title={r.title}
                    text={r.text}
                    images={r.images}
                    createdAt={r.createdAt}
                    likes={r.likes}
                    comments={r.comments?.length || 0}
                    commentsList={r.comments || []}
                    tags={r.tags}
                    rating={r.rating}
                    canEdit={isMyReview(r)}
                    onEdit={() => openEditModal(r)}
                    onDelete={handleDelete}
                    onAddComment={handleAddComment}
                    onDeleteComment={handleDeleteComment}
                  />
                </div>
              ))
            ) : (
              <div
                style={{
                  gridColumn: "span 3",
                  textAlign: "center",
                  padding: "60px 20px",
                  background: "#fff5f7",
                  borderRadius: 20,
                }}
              >
                <div style={{ fontSize: 48, marginBottom: 16 }}>🔍</div>
                <div
                  style={{
                    fontSize: 18,
                    fontWeight: 700,
                    color: "#333",
                    marginBottom: 8,
                  }}
                >
                  검색 결과가 없어요
                </div>
                <div style={{ color: "#888", fontSize: 14 }}>
                  다른 키워드로 검색해보세요!
                </div>
                <button
                  onClick={() => setSearchQuery("")}
                  style={{
                    marginTop: 16,
                    background: "linear-gradient(135deg, #ff4d88, #ff8a5c)",
                    border: "none",
                    borderRadius: 20,
                    padding: "10px 24px",
                    color: "#fff",
                    fontSize: 14,
                    fontWeight: 600,
                    cursor: "pointer",
                  }}
                >
                  전체 리뷰 보기
                </button>
              </div>
            )}
          </div>
        </div>

        {/* ✍ 내가 작성한 리뷰 섹션 */}
        {myReviews.length > 0 && (
          <section style={{ marginTop: 40 }}>
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: 16,
              }}
            >
              <h3 style={{ margin: 0, fontSize: 18 }}>✍ 내가 작성한 리뷰</h3>
              <div style={{ fontSize: 13, color: "#888" }}>
                {myReviews.length}개의 리뷰
              </div>
            </div>

            <div className="reviews-grid">
              {myReviews.map((r) => (
                <div key={r._id} className="feed-card">
                  <ReviewCard
                    id={r._id}
                    username={getUsernameFromAuthor(r.author)}
                    brand={r.brand}
                    product={r.product}
                    title={r.title}
                    text={r.text}
                    images={r.images}
                    createdAt={r.createdAt}
                    likes={r.likes}
                    comments={r.comments?.length || 0}
                    commentsList={r.comments || []}
                    tags={r.tags}
                    rating={r.rating}
                    canEdit={isMyReview(r)}
                    onEdit={() => openEditModal(r)}
                    onDelete={handleDelete}
                    onAddComment={handleAddComment}
                    onDeleteComment={handleDeleteComment}
                  />
                </div>
              ))}
            </div>
          </section>
        )}
      </div>

      {/* 수정 모달 */}
      {isEditModalOpen && editingItem && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.35)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 9999,
          }}
          onClick={closeEditModal}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              width: "100%",
              maxWidth: 520,
              background: "#fff",
              borderRadius: 24,
              padding: "24px 24px 20px",
              boxShadow: "0 20px 60px rgba(0,0,0,0.25)",
              position: "relative",
            }}
          >
            {/* 상단 헤더 */}
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: 16,
              }}
            >
              <h3 style={{ margin: 0, fontSize: 18, fontWeight: 800 }}>
                리뷰 수정하기
              </h3>
              <button
                type="button"
                onClick={closeEditModal}
                style={{
                  border: "none",
                  background: "transparent",
                  fontSize: 20,
                  cursor: "pointer",
                }}
              >
                ✕
              </button>
            </div>

            {/* 폼 */}
            <form onSubmit={handleEditSave}>
              <div style={{ marginBottom: 12 }}>
                <label
                  style={{
                    display: "block",
                    fontSize: 13,
                    fontWeight: 600,
                    marginBottom: 6,
                  }}
                >
                  제목
                </label>
                <input
                  type="text"
                  value={editForm.title}
                  onChange={(e) =>
                    setEditForm((prev) => ({ ...prev, title: e.target.value }))
                  }
                  style={{
                    width: "100%",
                    padding: "8px 10px",
                    borderRadius: 10,
                    border: "1px solid #e5e7eb",
                    fontSize: 14,
                  }}
                />
              </div>

              <div style={{ marginBottom: 12 }}>
                <label
                  style={{
                    display: "block",
                    fontSize: 13,
                    fontWeight: 600,
                    marginBottom: 6,
                  }}
                >
                  내용
                </label>
                <textarea
                  rows={6}
                  value={editForm.text}
                  onChange={(e) =>
                    setEditForm((prev) => ({ ...prev, text: e.target.value }))
                  }
                  style={{
                    width: "100%",
                    padding: "10px 12px",
                    borderRadius: 10,
                    border: "1px solid #e5e7eb",
                    fontSize: 14,
                    resize: "vertical",
                  }}
                />
              </div>

              <div style={{ marginBottom: 16 }}>
                <label
                  style={{
                    display: "block",
                    fontSize: 13,
                    fontWeight: 600,
                    marginBottom: 6,
                  }}
                >
                  평점 (0 ~ 5)
                </label>
                <input
                  type="number"
                  min={0}
                  max={5}
                  step={0.5}
                  value={editForm.rating}
                  onChange={(e) =>
                    setEditForm((prev) => ({
                      ...prev,
                      rating: e.target.value,
                    }))
                  }
                  style={{
                    width: 100,
                    padding: "6px 8px",
                    borderRadius: 10,
                    border: "1px solid #e5e7eb",
                    fontSize: 14,
                  }}
                />
              </div>

              <div
                style={{
                  display: "flex",
                  justifyContent: "flex-end",
                  gap: 8,
                }}
              >
                <button
                  type="button"
                  onClick={closeEditModal}
                  style={{
                    border: "none",
                    padding: "8px 14px",
                    borderRadius: 10,
                    background: "rgba(0,0,0,0.04)",
                    fontSize: 13,
                    cursor: "pointer",
                  }}
                >
                  취소
                </button>
                <button
                  type="submit"
                  style={{
                    border: "none",
                    padding: "8px 16px",
                    borderRadius: 10,
                    background: "linear-gradient(135deg,#ff4d88,#a855f7)",
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 13,
                    cursor: "pointer",
                  }}
                >
                  저장하기
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Feed;
